using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionAreaEnemyOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionAreaEnemy Omen Logic")]
public class BattleActionAreaEnemyOmenLogic : OmenLogic
{
	[Header("Enemies")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private DirectPurifyCorruptEnum directPurifyCorruptEnum;

	public override List<GameObject> GetTargets()
	{
		return currentCorruptedAnimals.activeCorruptedAnimals;
	}

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		List<GameObject> targets = GetTargets();
		if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectPurify)
		{
			for (int i = 0; i < targets.Count; i++)
			{
				targets[i].GetComponent<CorruptionStats>().Purify(actionValue, source, corruptionPurifyModifierEnum, playSFX);
			}
		}
		else if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectCorrupt)
		{
			for (int j = 0; j < targets.Count; j++)
			{
				targets[j].GetComponent<CorruptionStats>().Corrupt(actionValue, source, corruptionPurifyModifierEnum, playSFX);
			}
		}
		else
		{
			battleAction.AreaCastTargetAmount(targets, actionValue, source);
		}
	}
}
